ListNode MergeTwo(ListNode a, ListNode b) {
    var dummy = new ListNode();          // фиктивная голова: хвост есть всегда
    var tail = dummy;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = a ?? b;                  // остаток одного из списков
    return dummy.next;
}
