public sealed class FrameStats : MonoBehaviour {
    const int N = 120;                                   // около 2 секунд при 60 FPS
    readonly float[] ring = new float[N], scratch = new float[N];
    int head, count;

    void Update() {
        ring[head] = Time.unscaledDeltaTime * 1000f;     // мс
        head = (head + 1) % N;
        if (count < N) count++;
    }

    public float Percentile(float p) {                   // 0.5 — медиана, 0.99 — p99
        if (count == 0) return 0f;
        Array.Copy(ring, scratch, count);
        Array.Sort(scratch, 0, count);                   // 120 чисел: единицы микросекунд
        return scratch[(int)(p * (count - 1))];
    }
}
